            Enable sourcemap, at <output_file>.map

    -t, --targets <TARGETS>


    -V, --version
            Print version information
"""

def f32(x):
    try:
        return struct.unpack('f', struct.pack('f', float(x)))[0]
    except Exception:
        return float(x)

def fmt_num(v):
    # v is float (already f32-ish for parsed values, but calculations may be f64)
    try:
        v=float(v)
    except Exception:
        return str(v)
    if v==0:
        return "0"
    if math.isnan(v):
        return "NaN"
    if math.isinf(v):
        return "inf" if v>0 else "-inf"
    s=format(v, '.6g')
    # python uses e.g. 1e-05, 1.23457e+06
    if 'e' in s or 'E' in s:
        mant, exp_s = re.split('[eE]', s)
        exp=int(exp_s)
        if -6 <= exp < 0:
            # expand to decimal
            neg = mant.startswith('-')
            mant2 = mant.lstrip('-')
            if '.' in mant2:
                ip, fp = mant2.split('.')
            else:
                ip, fp = mant2, ''
            digits = ip+fp
            # value = digits *10^(exp - len(fp)) ; construct
            # Easier using Decimal with normalized string
            from decimal import Decimal
            d=Decimal(s)
            s=format(d, 'f')
        elif exp >= 0:
            from decimal import Decimal
            d=Decimal(s)
            s=format(d, 'f')
        else:
            # scientific keep mantissa, exp without leading zero / plus
            s = mant + 'e' + str(exp)
            return s
    # strip leading zero for -1< v <1, v!=0, decimal form
    if s.startswith('0.'):
        s='.'+s[2:]
    elif s.startswith('-0.'):
        s='-.'+s[3:]
    return s

def parse_float(s):
    try:
        return f32(float(s))
    except Exception:
        return 0.0

# ---------- identifiers / strings ----------
def decode_escape(text, i):
    # i at backslash, returns (decoded_char, next_i)
    # caller ensures not newline handling difference outside
    j=i+1
    if j>=len(text):
        return ('\ufffd', j)
    c=text[j]
    if c in '0123456789abcdefABCDEF':
        k=j
        hexs=''
        while k<len(text) and len(hexs)<6 and text[k] in '0123456789abcdefABCDEF':
            hexs+=text[k]; k+=1
        # optional whitespace
        if k<len(text) and text[k] in ' \t\n\r\f':
            if text[k]=='\r' and k+1<len(text) and text[k+1]=='\n':
                k+=2
            else:
                k+=1
        code=int(hexs,16)
        if code==0 or code>0x10FFFF or (0xD800<=code<=0xDFFF):
            return ('\ufffd', k)
        return (chr(code), k)
    else:
        return (c, j+1)

def encode_string(s):
    out='"'
    for ch in s:
        if ch=='"':
            out+='\\"'
        elif ch=='\\':
            out+='\\\\'
        elif ch=='\n':
            out+='\\a '
        elif ch=='\r':
            out+='\\d '
        elif ch=='\f':
            out+='\\c '
        elif ord(ch)==0:
            out+='\ufffd'
        elif ord(ch)<0x20 or ord(ch)==0x7f:
            out+='\\%x ' % ord(ch)
        else:
            out+=ch
    out+='"'
    return out

def is_ident_start(ch):
    return ch=='_' or ch.isalpha() or ord(ch)>=0x80
def is_ident_char(ch):
    return ch=='_' or ch=='-' or ch.isalnum() or ord(ch)>=0x80

def serialize_ident(name):
    # CSS identifier serialization (simplified)
    if name=='-':
        return '\\-'
    if name=='--':
        return '--'
    if name=='':
        return ''
    res=''
    for idx,ch in enumerate(name):
        o=ord(ch)
        if o==0:
            res+='\ufffd'
        elif (0x1<=o<=0x1f) or o==0x7f:
            res+='\\%x ' % o
        elif idx==0 and ch.isdigit():
            res+='\\%x ' % o
        elif idx==1 and ch.isdigit() and name[0]=='-':
            res+='\\%x ' % o
        elif ch=='-' or ch=='_' or ch.isalnum() or o>=0x80:
            res+=ch
        else:
            res+='\\'+ch
    return res

def valid_unquoted_url(s):
    if s=='':
        return False
    for ch in s:
        if ch.isspace() or ch in '"\'`()\\' or ord(ch)<0x20 or ord(ch)==0x7f:
            return False
    return True

def valid_ident_simple(s):
    # can be used unquoted as attr value etc, like CSS identifier (allow leading -)
    if not s:
