def clamp(v, lo, hi): return lo if v<lo else hi if v>hi else v

class Color:
    def __init__(self, r,g,b,a=1.0):
        self.r=float(r); self.g=float(g); self.b=float(b); self.a=float(a)
    def rounded(self):
        return (int(math.floor(clamp(self.r,0,255)+0.5)), int(math.floor(clamp(self.g,0,255)+0.5)), int(math.floor(clamp(self.b,0,255)+0.5)))
    def alpha_byte(self):
        return int(math.floor(clamp(self.a,0,1)*255+0.5))
    def __repr__(self): return f"Color{self.rounded()} a={self.a}"

def hex_for(r,g,b,a_byte=None):
    if a_byte is None or a_byte==255:
        if (r>>4)==(r&15) and (g>>4)==(g&15) and (b>>4)==(b&15):
            return "#%x%x%x" % (r>>4, g>>4, b>>4)
