def _srgb_from_linear(r,g,b,a):
    def gamma(u):
        u=clamp(u,0,1)
        return 12.92*u if u<=0.0031308 else 1.055*(u**(1/2.4))-0.055
    return Color(gamma(r)*255, gamma(g)*255, gamma(b)*255, a)

def xyz_d65_to_rgb(x,y,z,a):
    r= 3.2404542*x -1.5371385*y -0.4985314*z
    g=-0.9692660*x +1.8760108*y +0.0415560*z
    b= 0.0556434*x -0.2040259*y +1.0572252*z
    return _srgb_from_linear(r,g,b,a)

def lab_to_rgb(L,a,b,alpha=1.0):
    # L 0-100
    fy=(L+16)/116; fx=fy+a/500; fz=fy-b/200
    eps=216/24389; kap=24389/27
    def f_inv(t):
        return t**3 if t**3>eps else (116*t-16)/kap
    xn,yn,zn=0.96422,1.0,0.82521
    x=f_inv(fx)*xn; y=(L/kap if L<=kap*eps else fy**3)*yn; z=f_inv(fz)*zn
    # D50 to D65 Bradford
    # matrix D50->D65
    xd= x*0.9555766 + y*-0.0230393 + z*0.0631636
    yd= x*-0.0282895 + y*1.0099416 + z*0.0210077
    zd= x*0.0122982 + y*-0.0204830 + z*1.3299098
    return xyz_d65_to_rgb(xd,yd,zd,alpha)

def lch_to_rgb(L,C,H,alpha=1.0):
    a=C*math.cos(math.radians(H)); b=C*math.sin(math.radians(H))
    return lab_to_rgb(L,a,b,alpha)

def oklab_to_rgb(L,a,b,alpha=1.0):
    l_=L + 0.3963377774*a + 0.2158037573*b
    m_=L - 0.1055613458*a - 0.0638541728*b
    s_=L - 0.0894841775*a - 1.2914855480*b
    l_=l_**3; m_=m_**3; s_=s_**3
    r= +4.0767416621*l_ -3.3077115913*m_ +0.2309699292*s_
    g= -1.2684380046*l_ +2.6097574011*m_ -0.3413193965*s_
    b2= -0.0041960863*l_ -0.7034186147*m_ +1.7076147010*s_
    return _srgb_from_linear(r,g,b2,alpha)

def oklch_to_rgb(L,C,H,alpha=1.0):
    a=C*math.cos(math.radians(H)); b=C*math.sin(math.radians(H))
