# ---------- Value AST ----------
class Node:
    __slots__=('kind','tok','name','children','raw_name')
    def __init__(self, kind, tok=None, name=None, children=None):
        self.kind=kind; self.tok=tok; self.name=name; self.children=children or []
        self.raw_name=name
    def __repr__(self): return f"Node({self.kind},{self.tok!r},{self.name!r},{self.children!r})"

def err_from_token(tok, kind=None):
    tz=getattr(CTX,'tokenizer',None)
    if tz is not None and tok is not None:
        line,col=tz.loc(tok.offset)
        return ParseError(kind or f"UnexpectedToken({token_debug(tok)})", tok.offset if tok else 0, line, col)
    return ParseError(kind or "EndOfInput", tok.offset if tok else 0, 0, 1)

def nodes_from_tokens(toks):
    # returns list of nodes, raises on bad tokens
    pos=0
    def parse_seq(stops):
        nonlocal pos
        out=[]
        while pos < len(toks):
            t=toks[pos]
            if t.type in stops:
                break
            if t.type in (')',']','}'):
                # unmatched close in this context: treat as token? Caller may expect stop
                break
            if t.type=='comment' or t.type=='whitespace':
                pos+=1; continue
            if t.type in ('bad-string','bad-url'):
                raise err_from_token(t)
            if t.type=='function':
                pos+=1
                children=parse_seq({')'})
                if pos < len(toks) and toks[pos].type==')': pos+=1
                node=Node('func', tok=t, name=t.value, children=children)
                node.raw_name=t.value
                out.append(node); continue
            if t.type=='(':
                pos+=1; children=parse_seq({')'})
                if pos < len(toks) and toks[pos].type==')': pos+=1
                out.append(Node('paren', tok=t, children=children)); continue
            if t.type=='[':
                pos+=1; children=parse_seq({']'})
                if pos < len(toks) and toks[pos].type==']': pos+=1
                out.append(Node('bracket', tok=t, children=children)); continue
            if t.type=='{':
                pos+=1; children=parse_seq({'}'})
                if pos < len(toks) and toks[pos].type=='}': pos+=1
                out.append(Node('brace', tok=t, children=children)); continue
            out.append(Node('tok', tok=t)); pos+=1
        return out
    return parse_seq(set())

def split_nodes(nodes, sep_type='comma'):
    parts=[[]]
    for n in nodes:
        if n.kind=='tok' and n.tok.type==sep_type:
            parts.append([])
        else:
            parts[-1].append(n)
    return parts

def split_nodes_on(nodes, pred):
    parts=[[]]
    seps=[]
    for n in nodes:
        if pred(n):
            parts.append([]); seps.append(n)
        else:
            parts[-1].append(n)
    return parts

def node_is(n, type=None, val=None):
    return n.kind=='tok' and (type is None or n.tok.type==type) and (val is None or (str(n.tok.value).lower() if isinstance(n.tok.value,str) else n.tok.value)==val)

def first_token(n):
    if n.kind=='tok': return n.tok
    if n.children: return first_token(n.children[0])
    return n.tok
def last_token(n):
    if n.kind=='tok': return n.tok
    if n.children: return last_token(n.children[-1])
    return n.tok

def dim_to_css(val, unit):
    unit=(unit or '').lower()
    if unit=='ms' or unit=='s':
        sec=val if unit=='s' else val/1000.0
        ms= sec*1000.0
        cand_s=fmt_num(f32(sec))+'s'
        cand_ms=fmt_num(f32(ms))+'ms'
        if len(cand_ms) < len(cand_s): return cand_ms
        if len(cand_s) < len(cand_ms): return cand_s
        # tie keep original
        return cand_s if unit=='s' else cand_ms
    if unit=='rad':
        return fmt_num(f32(val*180.0/math.pi))+'deg'
    if unit=='dppx':
        return fmt_num(val)+'x'
    return fmt_num(val)+unit

ZEROABLE_UNITS={'px','em','rem','ex','ch','ic','cap','lh','rlh','vw','vh','vi','vb','vmin','vmax','svw','svh','lvw','lvh','dvw','dvh','cm','mm','in','pt','pc','q','mozmm'}
def length_to_css(val, unit):
    unit=(unit or '').lower()
    if val==0 and unit in ZEROABLE_UNITS:
        return "0"
    return fmt_num(val)+unit

def tok_to_css(t):
    if t is None: return ''
    ty=t.type
    if ty=='ident': return t.value
    if ty=='string': return encode_string(t.value)
    if ty=='hash':
        c=parse_color_hash(t.value)
        if c is not None:
            return color_to_css_context(c)
        return '#'+t.value
    if ty=='number': return fmt_num(t.value)
    if ty=='percentage': return fmt_num(t.value)+'%'
    if ty=='dimension': return dim_to_css(t.value, t.unit)
    if ty=='url':
        if CTX.minify and valid_unquoted_url(t.value):
            return 'url('+t.value+')'
        return 'url('+encode_string(t.value)+')'
    if ty=='at': return '@'+t.value
    if ty=='function': return t.value+'('
    if ty=='delim': return t.value
    if ty=='colon': return ':'
    if ty=='semicolon': return ';'
    if ty=='comma': return ','
    if ty=='CDO': return '<!--'
    if ty=='CDC': return '-->'
    return str(t.value) if t.value is not None else ''

def parse_color_hash(s):
    if not s: return None
    sl=s.lower()
    if len(sl) not in (3,4,6,8): return None
    if any(ch not in '0123456789abcdef' for ch in sl): return None
    if len(sl)==3:
        r=int(sl[0]*2,16); g=int(sl[1]*2,16); b=int(sl[2]*2,16); return Color(r,g,b,1)
    if len(sl)==4:
        r=int(sl[0]*2,16); g=int(sl[1]*2,16); b=int(sl[2]*2,16); a=int(sl[3]*2,16)/255; return Color(r,g,b,a)
    if len(sl)==6:
        return Color(int(sl[0:2],16),int(sl[2:4],16),int(sl[4:6],16),1)
    return Color(int(sl[0:2],16),int(sl[2:4],16),int(sl[4:6],16),int(sl[6:8],16)/255)

def flatten_leaves(nodes):
    out=[]
    for n in nodes:
        if n.kind=='tok': out.append(n.tok)
        elif n.kind=='func': out.append(Token('function', n.name)); out+=flatten_leaves(n.children)
        elif n.kind=='paren': out.append(Token('(','(')); out+=flatten_leaves(n.children); out.append(Token(')',')'))
        elif n.kind=='bracket': out.append(Token('[','[')); out+=flatten_leaves(n.children); out.append(Token(']',']'))
        elif n.kind=='brace': out.append(Token('{','{')); out+=flatten_leaves(n.children); out.append(Token('}','}'))
    return out

def comp_value(toks_or_node):
    # returns numeric component from a single token node/token: (value, is_percent)
    n=toks_or_node
    if isinstance(n, Node):
        if n.kind!='tok': return None
        t=n.tok
    else:
        t=n
    if t.type=='number': return (t.value, False)
    if t.type=='percentage': return (t.value, True)
    if t.type=='dimension':
        # angle units
        u=t.unit.lower()
        if u=='deg': return (t.value, False)
        if u=='rad': return (t.value*180/math.pi, False)
        if u=='grad': return (t.value*0.9, False)
        if u=='turn': return (t.value*360, False)
        return (t.value, False)
    return None

def parse_color_function(node):
    # node func, name rgb/rgba/hsl/hsla/hwb
    name=node.name.lower()
    # collect component nodes ignoring commas/slash (record slash position for alpha in modern)
    comps=[]
    alpha=None
    cur=[]
    # Split children by comma first if any comma present
    if any(n.kind=='tok' and n.tok.type=='comma' for n in node.children):
