# ---------- Value AST ----------
class Node:
    __slots__=('kind','tok','name','children','raw_name')
    def __init__(self, kind, tok=None, name=None, children=None):
        self.kind=kind; self.tok=tok; self.name=name; self.children=children or []
        self.raw_name=name
    def __repr__(self): return f"Node({self.kind},{self.tok!r},{self.name!r},{self.children!r})"

def err_from_token(tok, kind=None):
    tz=getattr(CTX,'tokenizer',None)
    if tz is not None and tok is not None:
        line,col=tz.loc(tok.offset)
        return ParseError(kind or f"UnexpectedToken({token_debug(tok)})", tok.offset if tok else 0, line, col)
    return ParseError(kind or "EndOfInput", tok.offset if tok else 0, 0, 1)

