# ---------- Generic node printing ----------
def is_word_tok(t):
    return t is not None and t.type in ('ident','number','percentage','dimension','hash','url','string','at')
def need_space(prev, cur):
    # prev, cur are Node
    if prev is None or cur is None: return False
    pt=last_token(prev); ct=first_token(cur)
    if pt is None or ct is None: return False
    # comma handled by join logic separately (this function called for non-comma adjacency as well)
    if ct.type=='comma' or pt.type=='comma': return False
    if ct.type in (')',']','}'): return False
    if pt.type in ('(','[','{','function'): return False
    if ct.type=='(' : return False
    # delim handling
    if ct.type=='delim':
        if ct.value in ('/','.', '|', '~','=','^','$','*'): # handled elsewhere; default no
            # but function? 
            if ct.value in ('+','-'):
                return is_word_tok(pt) or pt.type in (')',']')
            return False
        if ct.value in ('+','-'):
            return True
        if ct.value in ('&',): return False
        return False
    if pt.type=='delim':
        if pt.value in ('+','-'):
            return True
        if pt.value in ('/', '.', ':', '|'):
            return False
        if pt.value=='&':
            return False
        # other delims ( > etc ) spaces handled by selector printer not here
        return False
