    if pt.type=='colon':
        return not CTX.minify  # in pretty token lists like supports? caller overrides where not
    if ct.type=='colon':
        return False
    # word followed by word/function
    if is_word_tok(pt) and (is_word_tok(ct) or ct.type=='function' or ct.type=='('):
