def parse_calc_expr(nodes, pos=[0]):
    # recursive descent over node list
    # pos is list mutable in closure via object
    class P: pass
    p=P(); p.i=0; p.nodes=nodes
    def peek():
        return p.nodes[p.i] if p.i<len(p.nodes) else None
    def consume():
        n=peek(); p.i+=1; return n
    def parse_expr():
        node=parse_term()
        while True:
            n=peek()
            if n and n.kind=='tok' and n.tok.type=='delim' and n.tok.value in ('+','-'):
                op=consume().tok.value
                rhs=parse_term()
                node=make_bin(op,node,rhs)
            else: break
        return node
    def parse_term():
        node=parse_factor()
        while True:
            n=peek()
            if n and n.kind=='tok' and n.tok.type=='delim' and n.tok.value in ('*','/'):
                op=consume().tok.value
                rhs=parse_factor()
                node=make_bin(op,node,rhs)
            else: break
        return node
    def parse_factor():
        n=peek()
        if n is None: return CExpr(leaf=None)
        # unary +/-
        if n.kind=='tok' and n.tok.type=='delim' and n.tok.value in ('+','-'):
            op=consume().tok.value
            f=parse_factor()
            if f.num is not None:
                return CExpr(num=CNum(-f.num.val if op=='-' else f.num.val, f.num.unit, f.num.kind))
            if op=='-':
                # represent as -1 * f
                return make_bin('*', CExpr(num=CNum(-1,None,'number')), f)
            return f
        if n.kind=='tok':
            cn=cnum_from_token(n.tok)
            if cn is not None:
                consume(); return CExpr(num=cn)
            # ident leaf (e.g., var handled as func, but keywords?)
            consume(); return CExpr(leaf=n)
        if n.kind=='paren':
            consume(); return parse_calc_expr(n.children) if False else parse_inner(n.children)
        if n.kind=='func':
            consume()
            lname=n.name.lower()
            if lname in ('calc',):
                return parse_inner(n.children)
            if lname in ('min','max','clamp','round','mod','rem'):
                args_nodes=split_nodes(n.children,'comma')
                args=[parse_inner(a) for a in args_nodes]
                ev=evaluate_func(lname, args)
                if ev is not None: return CExpr(num=ev)
                return CExpr(func=lname,args=args)
            # var/env etc leaves
            return CExpr(leaf=n)
        consume(); return CExpr(leaf=n)
    def parse_inner(ns):
        # parse expression from node list ns using subparser
        return parse_calc_expr(ns)
    result=parse_expr()
    return result

def make_bin(op,left,right):
    # try fold if both nums
    if left.num is not None and right.num is not None:
        folded=fold_nums(op,left.num,right.num)
        if folded is not None:
            return CExpr(num=folded)
    # simplification identities
    if op=='+':
        if right.num is not None and right.num.val==0 and right.num.kind in ('number',):
            return left
        if left.num is not None and left.num.val==0 and left.num.kind in ('number',):
            return right
    if op=='*':
        if left.num is not None and left.num.kind=='number' and left.num.val==1: return right
        if right.num is not None and right.num.kind=='number' and right.num.val==1: return left
    return CExpr(op=op,left=left,right=right)

def convert_num(num, target_unit):
    # convert length absolute to target, angle to deg, time to target
    if num.kind=='length' and target_unit in ABS_LENGTH and num.unit in ABS_LENGTH:
        px=num.val*ABS_LENGTH[num.unit]
        return CNum(px/ABS_LENGTH[target_unit], target_unit, 'length')
    if num.kind=='time' and target_unit in TIME_UNITS:
        sec=num.val if num.unit=='s' else num.val/1000
        v=sec if target_unit=='s' else sec*1000
        return CNum(v,target_unit,'time')
    if num.kind=='angle' and target_unit=='deg':
        return CNum(num.val,'deg','angle')
    return None

def fold_nums(op,a,b):
    if op in ('+','-'):
        sign=1 if op=='+' else -1
        if a.kind!=b.kind:
            # percent + number etc no; length+percent no (returns None)
            # number zero special?
            return None
        if a.kind=='number':
            return CNum(f32(a.val+sign*b.val),None,'number')
        if a.kind=='percent':
            return CNum(f32(a.val+sign*b.val),None,'percent')
        if a.unit==b.unit:
            return CNum(f32(a.val+sign*b.val),a.unit,a.kind)
        # convert absolute
        conv=convert_num(b,a.unit)
        if conv: return CNum(f32(a.val+sign*conv.val),a.unit,a.kind)
        conv2=convert_num(a,b.unit)
        if conv2: return CNum(f32(conv2.val+sign*b.val),b.unit,b.kind)
        return None
    if op=='*':
        if a.kind=='number' and b.kind=='number':
            return CNum(f32(a.val*b.val),None,'number')
        if a.kind=='number':
            return CNum(f32(a.val*b.val),b.unit,b.kind)
        if b.kind=='number':
            return CNum(f32(a.val*b.val),a.unit,a.kind)
        return None
    if op=='/':
        if b.kind=='number':
            if b.val==0: return None
            return CNum(f32(a.val/b.val),a.unit,a.kind)
        if a.kind==b.kind:
            # same unit ratio
            bb=b
            if a.unit!=b.unit:
                conv=convert_num(b,a.unit)
                if conv is None: return None
                bb=conv
            if bb.val==0: return None
            return CNum(f32(a.val/bb.val),None,'number')
        return None
    return None

def nums_comparable(nums):
    # return list converted to common or None
    if not nums: return None
    first=nums[0]
    out=[]
    for n in nums:
        if n.kind!=first.kind: return None
        if n.unit==first.unit: out.append(n)
        else:
            c=convert_num(n, first.unit)
            if c is None: return None
            out.append(c)
    return out

def evaluate_func(name,args):
    if name in ('min','max'):
        if all(a.num is not None for a in args):
            comp=nums_comparable([a.num for a in args])
            if comp:
                chosen= min(comp, key=lambda x: x.val) if name=='min' else max(comp, key=lambda x: x.val)
                return chosen
    if name=='clamp' and len(args)==3 and all(a.num is not None for a in args):
        comp=nums_comparable([a.num for a in args])
        if comp:
            lo,mid,hi=comp
            v=max(lo.val, min(mid.val, hi.val))
            return CNum(v, lo.unit, lo.kind)
    return None

