        return f"{e.func}({inner})"
    if e.op:
        prec=1 if e.op in ('+','-') else 2
        left=cexpr_to_css(e.left, prec)
        right=cexpr_to_css(e.right, prec+ (1 if e.op in ('-','/') else 0))
