        # Our cexpr_to_css doesn't parenthesize itself; handle here:
        # Recompute with wrapping if child is binary with lower prec
        def wrap(child, need):
            s=cexpr_to_css(child)
            if child.op and ( (child.op in ('+','-') and need==2) or False):
                return '('+s+')'
            return s
        # simpler: rebuild
        ls=cexpr_to_css(e.left); rs=cexpr_to_css(e.right)
        if e.left.op and prec_of(e.left) < prec:
            ls='('+ls+')'
        if e.right.op and (prec_of(e.right) < prec or (e.op in ('-','/') and prec_of(e.right)==prec)):
            rs='('+rs+')'
        if e.op in ('+','-'):
            return f"{ls} {e.op} {rs}"
        else:
            if CTX.minify:
                return f"{ls}{e.op}{rs}"
            else:
                return f"{ls} {e.op} {rs}"
    return ''

def prec_of(e):
    if e.op in ('+','-'): return 1
    if e.op in ('*','/'): return 2
    return 3

def calc_function_to_css(node, top=False):
    name=node.name.lower()
    if name in ('min','max','clamp'):
        args_nodes=split_nodes(node.children,'comma')
        args=[parse_calc_expr(a) for a in args_nodes]
