    # register export
    if CTX.exports is not None and local not in CTX.exports:
        CTX.exports[local]={'name': result, 'composes': [], 'isReferenced': False}
    else:
        if CTX.exports is not None:
            # keep existing name (should be same)
            pass
    # prefix underscore if starts with digit
    if result and (result[0].isdigit() or (result[0]=='-' and len(result)>1 and result[1].isdigit())):
        result='_'+result
        if CTX.exports is not None and local in CTX.exports:
