def transform_nodes(nodes, zero_length=True, zero_angle=False, in_calc=False):
    out=[]
    for n in nodes:
        if n.kind=='tok':
            t=n.tok
            if t.type=='dimension' and zero_length and t.value==0 and t.unit.lower() in ZEROABLE_UNITS:
                out.append(Node('tok', tok=Token('number', 0.0, offset=t.offset))); continue
            if t.type=='dimension' and zero_angle and t.value==0 and t.unit.lower() in ANGLE_UNITS:
                out.append(Node('tok', tok=Token('number', 0.0, offset=t.offset))); continue
            out.append(n); continue
        if n.kind=='func':
            if n.name.lower() in ('var','env') and n.raw_name==n.name.lower(): # still transform generic? keep children as is for var names
                # transform children but do not zero? Original token lists in var fallback may convert colors - nodes_to_css handles. Keep.
                nn=Node('func', tok=n.tok, name=n.name, children=transform_nodes(n.children, zero_length=False)); nn.raw_name=n.raw_name; out.append(nn); continue
            nn=Node('func', tok=n.tok, name=n.name, children=transform_nodes(n.children, zero_length=zero_length, zero_angle=zero_angle)); nn.raw_name=n.raw_name; out.append(nn); continue
        nn=Node(n.kind, tok=n.tok, name=n.name, children=transform_nodes(n.children, zero_length=zero_length, zero_angle=zero_angle)); out.append(nn)
    return out

def generic_css(nodes, zero_length=True):
    return nodes_to_css(transform_nodes(nodes, zero_length=zero_length))

def comp_str(n):
