    for p in parts:
        if not p: continue
        if len(p)==1 and p[0].kind=='tok' and p[0].tok.type=='string':
            s=p[0].tok.value
            words=s.split()
            if words and all(valid_ident_simple(w) or serialize_ident(w) for w in words) and all(not w[0].isdigit() for w in words):
                # If string is a generic family name as single word, lightning may keep quote? We'll unquote (observed Arial/Times)
                fams.append(' '.join(serialize_ident(w) for w in words))
            else:
                fams.append(encode_string(s))
        else:
            # ident sequence or string/other
            items=[]
            for n in p:
                if n.kind=='tok' and n.tok.type=='ident': items.append(serialize_ident(n.tok.value))
                elif n.kind=='tok' and n.tok.type=='string':
                    s=n.tok.value; words=s.split()
                    if words: items.append(' '.join(serialize_ident(w) for w in words))
                    else: items.append(encode_string(s))
