def format_font(nodes):
    # find size node: dimension/percentage/ident size keyword/calc etc followed optionally slash
    # components token nodes before size are keywords/numbers
    # Identify index of node that looks like font-size: dimension/percentage or ident in size keywords or func
    size_keywords={'xx-small','x-small','small','medium','large','x-large','xx-large','xxx-large','smaller','larger','math'}
    size_idx=None
    for i,n in enumerate(nodes):
        if n.kind=='tok' and n.tok.type in ('dimension','percentage'): size_idx=i; break
        if n.kind=='tok' and n.tok.type=='ident' and n.tok.value.lower() in size_keywords: size_idx=i; break
        if n.kind=='func' and n.name.lower() in ('calc','min','max','clamp','var'): size_idx=i; break
    if size_idx is None:
        return generic_css(nodes)
    pre=nodes[:size_idx]
    rest=nodes[size_idx+1:]
    line_height=None
    # rest may start slash + lh, or size node itself has slash? nodes list includes delim '/'
    if rest and rest[0].kind=='tok' and rest[0].tok.type=='delim' and rest[0].tok.value=='/':
        if len(rest)>1: line_height=rest[1]; rest=rest[2:]
    # Pre classification
    style=''; variant=''; weight=''; stretch=''
    for n in pre:
        if n.kind=='tok' and n.tok.type=='ident':
            v=n.tok.value.lower()
            if v in ('italic','oblique'): style=v if not style else style+' '+generic_css([n])
            elif v=='small-caps': variant=v
            elif v in ('bold','bolder','lighter','normal'): 
                if v!='normal': weight = ('700' if (CTX.minify and v=='bold') else v)
                # normal weights dropped
            elif v in ('ultra-condensed','extra-condensed','condensed','semi-condensed','semi-expanded','expanded','extra-expanded','ultra-expanded'): stretch=v
            elif v=='normal': pass
            else: 
                # oblique angle etc generic
                if n.tok.type=='dimension': stretch=generic_css([n])
                else: style=(style+' '+v).strip()
        elif n.kind=='tok' and n.tok.type=='number':
            # weight number
            weight=fmt_num(n.tok.value)
        elif n.kind=='tok' and n.tok.type=='dimension':
            # oblique angle following italic/oblique? append to style
            style=(style+' '+generic_css([n])).strip()
        else:
            # e.g. oblique angle func etc
            pass
    size_str=generic_css([nodes[size_idx]])
    fam=format_family_list(rest) if rest else ''
    parts=[]
    for x in (style,variant,weight,stretch):
        if x: parts.append(x)
    sz=size_str
    if line_height is not None:
        lh=generic_css([line_height])
        sz+= (' / ' if not CTX.minify else '/')+lh
    parts.append(sz)
    if fam: parts.append(fam)
    return ' '.join(parts)

def format_gradient(node):
    name=node.name.lower()
    parts=split_nodes(node.children,'comma')
    out_parts=[]
    is_linear='linear' in name
    is_radial='radial' in name
    is_conic='conic' in name
    for pi,part in enumerate(parts):
        if not part:
            continue
        # color stop conversion / special first part
        if is_linear and pi==0:
            # direction: angle node, or 'to' keywords, or color stop
            if len(part)>=1 and part[0].kind=='tok' and part[0].tok.type=='ident' and part[0].tok.value.lower()=='to':
                out_parts.append(generic_css(part)); continue
            if len(part)==1 and part[0].kind=='tok' and part[0].tok.type=='dimension':
                out_parts.append(generic_css(part)); continue
        if is_radial and pi==0:
            # shape/size/position descriptors; remove 'at center' if position only center
            # Find ident 'at'
            at_idx=None
            for i,n in enumerate(part):
                if n.kind=='tok' and n.tok.type=='ident' and n.tok.value.lower()=='at': at_idx=i; break
            if at_idx is not None:
                after=part[at_idx+1:]
                if len(after)==1 and after[0].kind=='tok' and after[0].tok.type=='ident' and after[0].tok.value.lower()=='center':
                    part=part[:at_idx]
                    if not part:
                        # It was color stop? not
                        pass
                    else:
                        out_parts.append(generic_css(part)); continue
            # if first part contains a color node (hash/func/rgb ident named color) and no shape keywords, fall through to color stop
            keywords={'circle','ellipse','closest-side','farthest-side','closest-corner','farthest-corner','at'}
            if any(n.kind=='tok' and n.tok.type=='ident' and n.tok.value.lower() in keywords for n in part) or any(n.kind=='tok' and n.tok.type in ('dimension','percentage') for n in part):
                # could still be color stop with positions, but shapes have keywords above/lengths. If first token is color, treat as stop.
                first_is_color = node_as_color(part[0]) is not None or (part[0].kind=='tok' and part[0].tok.type=='ident' and part[0].tok.value.lower() in NAMED)
                if not first_is_color:
                    out_parts.append(generic_css(part)); continue
        if is_conic and pi==0:
            # from/at defaults
            filtered=[]; skip_next=False
            # Remove 'from 0deg' and 'at center' simplistic
            i=0; changed=False
            while i<len(part):
                n=part[i]
                if n.kind=='tok' and n.tok.type=='ident' and n.tok.value.lower()=='from' and i+1<len(part):
                    if generic_css([part[i+1]]) in ('0','0deg'): i+=2; changed=True; continue
                if n.kind=='tok' and n.tok.type=='ident' and n.tok.value.lower()=='at' and i+1<len(part) and part[i+1].kind=='tok' and part[i+1].tok.value.lower()=='center':
                    i+=2; changed=True; continue
                filtered.append(n); i+=1
            if changed:
                if filtered: out_parts.append(generic_css(filtered)); continue
                else: continue
            # if has from/at nondefault, keep as prefix part if it is not color stop
            if any(n.kind=='tok' and n.tok.type=='ident' and n.tok.value.lower() in ('from','at') for n in part):
                first_is_color=node_as_color(part[0]) is not None
                if not first_is_color:
                    out_parts.append(generic_css(part)); continue
        # color stop
        if part:
            first=part[0]
            c=node_as_color(first)
            if c is not None:
                col_str=color_to_css_context(c)
                rest_str=''
                rest=part[1:]
                # double position handling for old targets
                if len(rest)>=2 and not supports('double_position'):
                    sep=', ' if not CTX.minify else ','
                    p1=generic_css([rest[0]]); p2=generic_css([rest[1]])
                    extra=rest[2:]
                    s1=col_str+' '+p1
                    s2=col_str+' '+p2
                    if extra: s2+=' '+' '.join(generic_css([x]) for x in extra)
                    out_parts.append(s1); out_parts.append(s2); continue
                if rest:
                    rest_str=' '+' '.join(generic_css([x]) for x in rest)
                out_parts.append(col_str+rest_str); continue
            # modern color function etc
            if first.kind=='func' and first.name.lower() in ('lab','lch','oklab','oklch','color'):
                col_str=nodes_to_css([first]) if False else node_to_css(first)
                # node_to_css for lab will generic; ok
                rest=part[1:]
                rest_str=' '+' '.join(generic_css([x]) for x in rest) if rest else ''
                out_parts.append(col_str+rest_str); continue
        out_parts.append(generic_css(part))
    sep=', ' if not CTX.minify else ','
    return node.name.lower()+'('+sep.join(out_parts)+')'

def background_position_str(nodes):
    # nodes list of position tokens (1-4)
    strs=[generic_css([n]) for n in nodes]
    lowers=[n.tok.value.lower() if n.kind=='tok' and n.tok.type=='ident' else None for n in nodes]
    if len(nodes)==1:
        v=lowers[0]
        if v=='left': return '0'
        if v=='right': return '100%'
        if v=='center': return 'center' if not CTX.minify else '50%'
        if v in ('top','bottom'): return strs[0]
        return strs[0]
    if len(nodes)==2 and all(x is not None for x in lowers):
        x=None; y=None
        for v in lowers:
            if v in ('left','right'): x=v
            elif v in ('top','bottom'): y=v
            elif v=='center':
                if x is None: x='center'
                elif y is None: y='center'
        if x is not None and y is not None:
            # map
            xm={'left':'0','right':'100%','center':'center'}
            ym={'top':'0','bottom':'100%','center':'center'}
            xs=xm[x]; ys=ym[y]
            if xs=='center' and ys=='center': return 'center' if not CTX.minify else '50%'
            if xs=='center': return ('center ' if not CTX.minify else '50% ')+ys if False else (('center' if not CTX.minify else '50%')+' '+ys)
            if ys=='center': return xs+' '+('center' if not CTX.minify else '50%')
            return xs+' '+ys
