                    if extra: s2+=' '+' '.join(generic_css([x]) for x in extra)
                    out_parts.append(s1); out_parts.append(s2); continue
                if rest:
                    rest_str=' '+' '.join(generic_css([x]) for x in rest)
                out_parts.append(col_str+rest_str); continue
            # modern color function etc
            if first.kind=='func' and first.name.lower() in ('lab','lch','oklab','oklch','color'):
                col_str=nodes_to_css([first]) if False else node_to_css(first)
                # node_to_css for lab will generic; ok
                rest=part[1:]
                rest_str=' '+' '.join(generic_css([x]) for x in rest) if rest else ''
                out_parts.append(col_str+rest_str); continue
        out_parts.append(generic_css(part))
    sep=', ' if not CTX.minify else ','
    return node.name.lower()+'('+sep.join(out_parts)+')'

def background_position_str(nodes):
    # nodes list of position tokens (1-4)
    strs=[generic_css([n]) for n in nodes]
    lowers=[n.tok.value.lower() if n.kind=='tok' and n.tok.type=='ident' else None for n in nodes]
    if len(nodes)==1:
        v=lowers[0]
        if v=='left': return '0'
        if v=='right': return '100%'
        if v=='center': return 'center' if not CTX.minify else '50%'
        if v in ('top','bottom'): return strs[0]
        return strs[0]
    if len(nodes)==2 and all(x is not None for x in lowers):
        x=None; y=None
        for v in lowers:
            if v in ('left','right'): x=v
            elif v in ('top','bottom'): y=v
            elif v=='center':
                if x is None: x='center'
                elif y is None: y='center'
        if x is not None and y is not None:
            # map
            xm={'left':'0','right':'100%','center':'center'}
            ym={'top':'0','bottom':'100%','center':'center'}
            xs=xm[x]; ys=ym[y]
            if xs=='center' and ys=='center': return 'center' if not CTX.minify else '50%'
            if xs=='center': return ('center ' if not CTX.minify else '50% ')+ys if False else (('center' if not CTX.minify else '50%')+' '+ys)
            if ys=='center': return xs+' '+('center' if not CTX.minify else '50%')
            return xs+' '+ys
    # 3-4 components: preserve but keyword+offset etc generic
    return ' '.join(strs)

def format_background(nodes, prop='background'):
    # layers
    layers=split_nodes(nodes,'comma')
    out_layers=[]
    for li,layer in enumerate(layers):
        if not layer: continue
        color=None; image=None; position=[]; size=[]; repeat=[]; attachment=None; boxes=[]
        in_size=False
        i=0
        # background shorthand token classification
        while i<len(layer):
            n=layer[i]
            if n.kind=='tok' and n.tok.type=='delim' and n.tok.value=='/':
                in_size=True; i+=1; continue
            # color
            c=node_as_color(n)
            if c is not None and color is None and not in_size:
                color=color_to_css_context(c); i+=1; continue
            if n.kind=='func' and n.name.lower().endswith('gradient'):
                image=format_gradient(n); i+=1; continue
            if n.kind=='tok' and n.tok.type=='url':
                image=tok_to_css(n); i+=1; continue
            if n.kind=='func' and n.name.lower()=='url':
                image=node_to_css(n); i+=1; continue
            if n.kind=='tok' and n.tok.type=='ident':
                v=n.tok.value.lower()
                if v=='none' and image is None: image='none'; i+=1; continue
                if v in ('repeat','no-repeat','space','round','repeat-x','repeat-y'):
                    repeat.append(v); i+=1; continue
                if v in ('scroll','fixed','local'):
                    attachment=v; i+=1; continue
                if v in ('border-box','padding-box','content-box','text'):
                    boxes.append(v); i+=1; continue
                if v in ('left','right','top','bottom','center'):
                    if in_size: size.append(n)
                    else: position.append(n)
                    i+=1; continue
                # unknown ident as image? (e.g., cross-fade etc func handled)
                if image is None and v not in ('left','right','top','bottom','center'):
                    # could be position? already
                    position.append(n) if not in_size else size.append(n)
                    i+=1; continue
            # lengths/percentages etc go to position/size
            if in_size: size.append(n)
            else: position.append(n)
            i+=1
        parts=[]
        # Lightning order observed: color, image, position, repeat... For simple: url + position + repeat; color before url? #fff url -> color first
        if color: parts.append(color)
        if image: parts.append(image)
        if position: parts.append(background_position_str(position))
        if size:
            sz=' '.join(generic_css([x]) for x in size)
            # attach slash to previous position if exists
            if parts and position:
                parts[-1]=parts[-1]+((' / ' if not CTX.minify else '/')+sz)
            else:
                parts.append(sz)
        if repeat: parts.append(' '.join(repeat))
        if attachment: parts.append(attachment)
        if boxes: parts.extend(boxes)  # simplified origin/clip handling
        s=' '.join(parts)
        # special default cases
        if not CTX.minify:
            if s=='none' or s=='':
                # background:transparent -> color transparent but transformed? If original layer had only transparent color, color_to_css gives #0000 not none. Caller special handling before.
                pass
        out_layers.append(s)
    sep=', ' if not CTX.minify else ','
    result=sep.join(out_layers)
    # special cases mapping when whole value is just none/transparent in minify etc.
    # Determine original single semantics:
    if len(layers)==1:
        # if only image none and no other
        vals=[generic_css([n]) for n in layers[0]]
        # We'll handle in caller transform_value for background
        pass
    return result

