def reduce_box(vals):
    # vals list strings 1-4 representing top right bottom left
    if len(vals)==4:
        if vals[0]==vals[1]==vals[2]==vals[3]: return [vals[0]]
        if vals[0]==vals[2] and vals[1]==vals[3]: return vals[:2]
        if vals[1]==vals[3]: return vals[:3]
    return vals

def expand_box(vals):
    if len(vals)==1: return [vals[0]]*4
    if len(vals)==2: return [vals[0],vals[1],vals[0],vals[1]]
    if len(vals)==3: return [vals[0],vals[1],vals[2],vals[1]]
    if len(vals)>=4: return vals[:4]
    return vals

def format_family_list(nodes):
