def format_font(nodes):
    # find size node: dimension/percentage/ident size keyword/calc etc followed optionally slash
    # components token nodes before size are keywords/numbers
    # Identify index of node that looks like font-size: dimension/percentage or ident in size keywords or func
    size_keywords={'xx-small','x-small','small','medium','large','x-large','xx-large','xxx-large','smaller','larger','math'}
    size_idx=None
    for i,n in enumerate(nodes):
        if n.kind=='tok' and n.tok.type in ('dimension','percentage'): size_idx=i; break
        if n.kind=='tok' and n.tok.type=='ident' and n.tok.value.lower() in size_keywords: size_idx=i; break
        if n.kind=='func' and n.name.lower() in ('calc','min','max','clamp','var'): size_idx=i; break
    if size_idx is None:
        return generic_css(nodes)
    pre=nodes[:size_idx]
    rest=nodes[size_idx+1:]
    line_height=None
    # rest may start slash + lh, or size node itself has slash? nodes list includes delim '/'
    if rest and rest[0].kind=='tok' and rest[0].tok.type=='delim' and rest[0].tok.value=='/':
        if len(rest)>1: line_height=rest[1]; rest=rest[2:]
    # Pre classification
    style=''; variant=''; weight=''; stretch=''
    for n in pre:
        if n.kind=='tok' and n.tok.type=='ident':
            v=n.tok.value.lower()
            if v in ('italic','oblique'): style=v if not style else style+' '+generic_css([n])
            elif v=='small-caps': variant=v
            elif v in ('bold','bolder','lighter','normal'): 
                if v!='normal': weight = ('700' if (CTX.minify and v=='bold') else v)
                # normal weights dropped
            elif v in ('ultra-condensed','extra-condensed','condensed','semi-condensed','semi-expanded','expanded','extra-expanded','ultra-expanded'): stretch=v
            elif v=='normal': pass
            else: 
                # oblique angle etc generic
                if n.tok.type=='dimension': stretch=generic_css([n])
                else: style=(style+' '+v).strip()
        elif n.kind=='tok' and n.tok.type=='number':
            # weight number
            weight=fmt_num(n.tok.value)
        elif n.kind=='tok' and n.tok.type=='dimension':
            # oblique angle following italic/oblique? append to style
            style=(style+' '+generic_css([n])).strip()
        else:
            # e.g. oblique angle func etc
            pass
    size_str=generic_css([nodes[size_idx]])
    fam=format_family_list(rest) if rest else ''
    parts=[]
    for x in (style,variant,weight,stretch):
        if x: parts.append(x)
    sz=size_str
    if line_height is not None:
        lh=generic_css([line_height])
        sz+= (' / ' if not CTX.minify else '/')+lh
    parts.append(sz)
    if fam: parts.append(fam)
    return ' '.join(parts)

def format_gradient(node):
    name=node.name.lower()
    parts=split_nodes(node.children,'comma')
    out_parts=[]
    is_linear='linear' in name
    is_radial='radial' in name
    is_conic='conic' in name
    for pi,part in enumerate(parts):
        if not part:
            continue
        # color stop conversion / special first part
        if is_linear and pi==0:
            # direction: angle node, or 'to' keywords, or color stop
            if len(part)>=1 and part[0].kind=='tok' and part[0].tok.type=='ident' and part[0].tok.value.lower()=='to':
                out_parts.append(generic_css(part)); continue
            if len(part)==1 and part[0].kind=='tok' and part[0].tok.type=='dimension':
                out_parts.append(generic_css(part)); continue
        if is_radial and pi==0:
            # shape/size/position descriptors; remove 'at center' if position only center
            # Find ident 'at'
            at_idx=None
            for i,n in enumerate(part):
                if n.kind=='tok' and n.tok.type=='ident' and n.tok.value.lower()=='at': at_idx=i; break
            if at_idx is not None:
                after=part[at_idx+1:]
                if len(after)==1 and after[0].kind=='tok' and after[0].tok.type=='ident' and after[0].tok.value.lower()=='center':
                    part=part[:at_idx]
