                        # It was color stop? not
                        pass
                    else:
                        out_parts.append(generic_css(part)); continue
            # if first part contains a color node (hash/func/rgb ident named color) and no shape keywords, fall through to color stop
            keywords={'circle','ellipse','closest-side','farthest-side','closest-corner','farthest-corner','at'}
            if any(n.kind=='tok' and n.tok.type=='ident' and n.tok.value.lower() in keywords for n in part) or any(n.kind=='tok' and n.tok.type in ('dimension','percentage') for n in part):
                # could still be color stop with positions, but shapes have keywords above/lengths. If first token is color, treat as stop.
                first_is_color = node_as_color(part[0]) is not None or (part[0].kind=='tok' and part[0].tok.type=='ident' and part[0].tok.value.lower() in NAMED)
                if not first_is_color:
                    out_parts.append(generic_css(part)); continue
        if is_conic and pi==0:
            # from/at defaults
            filtered=[]; skip_next=False
            # Remove 'from 0deg' and 'at center' simplistic
            i=0; changed=False
            while i<len(part):
                n=part[i]
                if n.kind=='tok' and n.tok.type=='ident' and n.tok.value.lower()=='from' and i+1<len(part):
                    if generic_css([part[i+1]]) in ('0','0deg'): i+=2; changed=True; continue
                if n.kind=='tok' and n.tok.type=='ident' and n.tok.value.lower()=='at' and i+1<len(part) and part[i+1].kind=='tok' and part[i+1].tok.value.lower()=='center':
                    i+=2; changed=True; continue
                filtered.append(n); i+=1
            if changed:
                if filtered: out_parts.append(generic_css(filtered)); continue
                else: continue
            # if has from/at nondefault, keep as prefix part if it is not color stop
            if any(n.kind=='tok' and n.tok.type=='ident' and n.tok.value.lower() in ('from','at') for n in part):
