TIMING_KEYWORDS={'ease','linear','ease-in','ease-out','ease-in-out','step-start','step-end'}
def format_transition(nodes):
    items=split_nodes(nodes,'comma')
    outs=[]
    for item in items:
        prop=None; times=[]; timing=None; others=[]
        for n in item:
            if n.kind=='tok' and n.tok.type=='dimension' and n.tok.unit.lower() in ('s','ms'):
                times.append(n); continue
            if n.kind=='tok' and n.tok.type=='ident' and n.tok.value.lower() in TIMING_KEYWORDS:
                timing=n.tok.value.lower(); continue
            if n.kind=='func' and n.name.lower() in ('cubic-bezier','steps','linear'):
                timing=node_to_css(n); continue
            if n.kind=='tok' and n.tok.type=='ident' and prop is None:
                prop=n.tok.value.lower(); continue
            others.append(n)
        parts=[]
        if prop: parts.append(prop)
        else:
            if others: parts.append(generic_css(others))
        if times:
            dur=times[0]
            if not (dur.tok.value==0):
                parts.append(dim_to_css(dur.tok.value, dur.tok.unit))
            # if duration 0 and no other? transition:all 0s -> all
            if len(times)>1 and times[1].tok.value!=0:
                # timing before delay output order: duration timing delay
                if timing and timing!='ease': 
                    # will add below, need order
                    pass
                # We'll reconstruct below
                pass
        if timing and timing!='ease':
            parts.append(timing)
        elif timing=='ease':
            pass
        if len(times)>1 and times[1].tok.value!=0:
            parts.append(dim_to_css(times[1].tok.value, times[1].tok.unit))
        # If no duration but timing etc, parts already
        if not parts and times:
            parts.append(dim_to_css(times[0].tok.value, times[0].tok.unit))
        outs.append(' '.join(parts))
    sep=', ' if not CTX.minify else ','
    return sep.join(outs)

def format_animation(nodes):
    items=split_nodes(nodes,'comma')
    outs=[]
    for item in items:
        name=None; times=[]; timing=None; iteration=None; direction=None; fill=None; play=None
        others=[]
        for n in item:
            if n.kind=='tok' and n.tok.type=='dimension' and n.tok.unit.lower() in ('s','ms'):
                times.append(n); continue
            if n.kind=='tok' and n.tok.type=='ident':
                v=n.tok.value.lower()
                if v in TIMING_KEYWORDS: timing=v; continue
                if v=='infinite': iteration='infinite'; continue
                if v in ('normal','reverse','alternate','alternate-reverse'): direction=v if v!='normal' else None; continue
                if v in ('forwards','backwards','both'): fill=v; continue
                if v in ('running','paused'): play=v if v!='running' else None; continue
                if v=='none': name='none'; continue
                # animation name (preserve case)
                if name is None: name=n.tok.value; 
                else: others.append(n)
                continue
            if n.kind=='tok' and n.tok.type=='number':
                iteration=fmt_num(n.tok.value); continue
            if n.kind=='func' and n.name.lower() in ('cubic-bezier','steps','linear'):
                timing=node_to_css(n); continue
            if n.kind=='tok' and n.tok.type=='string':
                if name is None: name=encode_string(n.tok.value)
                continue
            if n.kind=='func' and CTX.css_modules is not None:
                others.append(n); continue
