            # register referenced
            renamed=css_module_rename(name)
            if name in CTX.exports: CTX.exports[name]['isReferenced']=True
            name=renamed
        # Output order: duration, timing, delay, iteration, direction, fill, play, name
        parts=[]
        if times:
            # if only duration and name none/default -> observed outputs 'none' (drop duration). Implement: if name=='none' or name is None and ??? 
