            if times[1].tok.value!=0: parts.append(dim_to_css(times[1].tok.value, times[1].tok.unit))
            # if delay 0 omit; but if we omitted timing etc order fine
        if iteration and iteration!='1': parts.append(iteration)
        if direction: parts.append(direction)
        if fill: parts.append(fill)
        if play: parts.append(play)
        if others:
            parts.append(generic_css(others))
        if name:
            parts.append(name)
        # special cases
        if not parts:
            parts.append('none')
        # If name is none and there is a duration, original behavior: 'animation:1s' -> 'none', 'animation:none 1s' -> 'none'
        # That suggests when name == none, they output only none regardless? But animation: none 2s ease... would lose. Check later tests; implement if name=='none': return 'none'
        if name=='none':
            outs.append('none'); continue
        if name is None and times:
            # e.g. animation:1s -> none (name default none)
            outs.append('none'); continue
        # remove leading 0s duration if it's only before name? animation:0s spin (?) duration default, maybe drop? Keep if parts length>1 and first is 0s and ??? Probe later.
        # If duration is 0s and timing etc none, name present: likely prints name only? We'll keep.
        outs.append(' '.join(parts))
    sep=', ' if not CTX.minify else ','
