            if lname in ('rotate','rotatex','rotatey','rotatez','rotate3d','skewx','skewy') or lname.startswith('rotate') or lname.startswith('skew'):
                # angle args: transform dimension zero etc - generic_css already dim_to_css; convert 0deg tokens inside args nodes
                new_args=[]
                for a in args:
