    def parse_rule_list(self, top=False, in_style=False):
        rules=[]
        while True:
            self.skip_ws(collect_license=top)
            if self.i>=len(self.toks): break
            t=self.toks[self.i]
            if t.type=='}': break
            if t.type=='semicolon': self.i+=1; continue
            try:
                r=self.parse_rule(in_style=in_style)
            except ParseError as e:
                if not CTX.error_recovery: raise
                CTX.recovery_errors.append(e)
                self.recover_rule()
                continue
