        # skip until after balanced block or semicolon
        depth=0; seen_block=False
        while self.i<len(self.toks):
            t=self.toks[self.i]; self.i+=1
            if t.type in ('function','(','[','{'): depth+=1; seen_block=seen_block or t.type=='{'
            elif t.type in (')',']','}'):
