def vendor_sort_same_base(entries):
    # For entries with same base, order by vendor index within slots occupied by that base
    from collections import defaultdict
    slots=defaultdict(list)
    for i,e in enumerate(entries): slots[e.base if not e.prop.startswith('--') else e.prop].append(i)
    # but base for prefixed is stripped, prop differs; grouping by base could group transform and -webkit-transform
    # Recompute group key: base property (without vendor) -- Entry.base already is that for transformed; for unknown entries base=prop
    groups=defaultdict(list)
