def needed_prefixes(base):
    if not CTX.targets_present or CTX.targets is None: return []
    table=PREFIX_SUPPORT.get(base)
    if not table: return []
    needed=[]
    for prefix, browsers in table.items():
        for browser, support_major in browsers.items():
            if browser in CTX.targets:
                ver=CTX.targets[browser]>>16
                if ver < support_major:
                    needed.append(prefix); break
    # order webkit, moz, ms, o as in VENDOR_PREFIXES
    order={p:i for i,p in enumerate(VENDOR_PREFIXES)}
    return sorted(set(needed), key=lambda p: order.get(p,9))

def apply_prefixes(entries):
    if not CTX.targets_present:
        return vendor_sort_same_base(entries)
    # Remove unneeded existing prefixed entries; add needed.
    existing_prefix_by_base={}
    for e in entries:
        if e.vendor!=4:
            existing_prefix_by_base.setdefault(e.base, set()).add(VENDOR_PREFIXES[e.vendor])
    out=[]
    # First filter existing prefixed entries: keep only if needed for its base (or if no unprefixed counterpart? Lightning behavior uncertain; if prefix is needed keep, else drop prefixed entry when there's an unprefixed? We'll drop if not needed and base is in PREFIX_SUPPORT)
    has_unprefixed=set(e.base for e in entries if e.vendor==4)
    for e in entries:
        if e.vendor!=4 and e.base in PREFIX_SUPPORT:
            pref=VENDOR_PREFIXES[e.vendor]
            if pref not in needed_prefixes(e.base):
                # drop this prefixed declaration (if unprefixed exists or not? If only prefixed, converting? For now drop only if unprefixed exists; else keep? Test may expect removal... keep logic: if no unprefixed, keep the prefixed as is? Original may remove and keep none? We'll keep if no unprefixed to avoid losing.
                if e.base in has_unprefixed:
                    continue
                else:
                    out.append(e); continue
            out.append(e); continue
        out.append(e)
    entries=out
    # Add needed for unprefixed entries
    result=[]
    existing=set((e.prop,e.important) for e in entries)
    for e in entries:
        if e.vendor==4 and e.base in PREFIX_SUPPORT:
            need=needed_prefixes(e.base)
            for pref in need:
