def handle_composes(rd, owner_local):
    if owner_local is None: return
    toks=strip_ws_toks(rd.toks)
    # Find owner export ensure
    owner_name=css_module_rename(owner_local)
    # owner export entry exists
    names=[]; spec=None; from_global=False
    i=0
    while i<len(toks):
        t=toks[i]
        if t.type=='ident' and t.value.lower()=='from':
            if i+1<len(toks):
                nt=toks[i+1]
                if nt.type=='string': spec=nt.value; i+=2; break
                if nt.type=='ident' and nt.value.lower()=='global': from_global=True; i+=2; break
            break
        if t.type=='ident': names.append(t.value)
        i+=1
    if CTX.exports is None: return
    if owner_local not in CTX.exports:
        # created via rename above (it registered under owner_local)
        pass
    owner_entry=CTX.exports.get(owner_local)
    if owner_entry is None: return
    for nm in names:
        if spec is not None:
            owner_entry['composes'].append({'name': nm, 'specifier': spec, 'type': 'dependency'})
        elif from_global:
            owner_entry['composes'].append({'name': nm, 'type': 'global'})
        else:
            renamed=css_module_rename(nm)
            owner_entry['composes'].append({'name': renamed, 'type': 'local'})

