# ---------- Declaration processing ----------
def dedup_entries(entries):
    # entries list Entry; known/custom dedup by prop+important keeping last decl_id entries; unknown (known=False) keep all
    # Determine last decl_id per key for known
    last={}
    for e in entries:
        if e.known:
            last[(e.prop,e.important)]=e.decl_id
    out=[]
    for e in entries:
        if not e.known:
            out.append(e); continue
        if last.get((e.prop,e.important))==e.decl_id:
            out.append(e)
    return out

def vendor_sort_same_base(entries):
    # For entries with same base, order by vendor index within slots occupied by that base
    from collections import defaultdict
    slots=defaultdict(list)
    for i,e in enumerate(entries): slots[e.base if not e.prop.startswith('--') else e.prop].append(i)
    # but base for prefixed is stripped, prop differs; grouping by base could group transform and -webkit-transform
    # Recompute group key: base property (without vendor) -- Entry.base already is that for transformed; for unknown entries base=prop
    groups=defaultdict(list)
    for i,e in enumerate(entries):
        groups[e.base].append(i)
    for base, idxs in groups.items():
        if len(idxs)>1:
            sorted_entries=sorted([entries[i] for i in idxs], key=lambda e: e.vendor)
            # Only apply if they share same full base (i.e., props are vendor variants of same)
            # Check props differ only by prefix
            bases=set()
            for e in sorted_entries:
                b,_=split_vendor(e.prop) if not e.prop.startswith('--') else (e.prop,4)
                bases.add(b)
            if len(bases)==1:
                for pos,ent in zip(idxs, sorted_entries):
                    entries[pos]=ent
    return entries

