def split_selector_str(s):
    parts=[]; depth=0; cur=''
    for ch in s:
        if ch in '([': depth+=1
        elif ch in ')]': depth-=1
        if ch==',' and depth==0:
            parts.append(cur.strip()); cur=''
        else: cur+=ch
    if cur.strip(): parts.append(cur.strip())
    return parts

def supports_logical(kind):
    if not CTX.targets_present or CTX.targets is None: return True
    # thresholds
    if kind=='shorthand':
        table={'chrome':87,'firefox':66,'safari':15,'edge':87,'opera':73,'ios_saf':15,'android':87,'samsung':14,'ie':None}
    else:
        table={'chrome':69,'firefox':41,'safari':13,'edge':79,'opera':56,'ios_saf':13,'android':69,'samsung':10,'ie':None}
    for b,ver in CTX.targets.items():
        if b not in table: continue
        need=table[b]
        if need is None: return False
        if (ver>>16) < need: return False
    return True

