def split_selector_str(s):
    parts=[]; depth=0; cur=''
    for ch in s:
        if ch in '([': depth+=1
        elif ch in ')]': depth-=1
        if ch==',' and depth==0:
            parts.append(cur.strip()); cur=''
        else: cur+=ch
    if cur.strip(): parts.append(cur.strip())
    return parts

def supports_logical(kind):
    if not CTX.targets_present or CTX.targets is None: return True
    # thresholds
    if kind=='shorthand':
        table={'chrome':87,'firefox':66,'safari':15,'edge':87,'opera':73,'ios_saf':15,'android':87,'samsung':14,'ie':None}
    else:
        table={'chrome':69,'firefox':41,'safari':13,'edge':79,'opera':56,'ios_saf':13,'android':69,'samsung':10,'ie':None}
    for b,ver in CTX.targets.items():
        if b not in table: continue
        need=table[b]
        if need is None: return False
        if (ver>>16) < need: return False
    return True

def transform_rule(rule):
    if rule.get('processed'): return [rule]
    k=rule['kind']
    if k=='style':
        return transform_style_rule(rule)
    if k=='at_block':
        # custom media expansion removal etc handled in formatting; transform inner
        inner=[]
        for r in rule['rules']:
            inner.extend(transform_rule(r))
        inner=merge_rules(inner)
        if not inner and rule['name'] not in ('layer',):
            return []
        nr=dict(rule); nr['rules']=inner; nr['processed']=True
        return [nr]
    if k=='nested_at':
        # only occurs inside style, handled there
        return [rule]
    if k=='at_decl':
        nr=dict(rule); nr['entries']=process_decl_block_simple(rule['decls']); nr['processed']=True; return [nr]
    if k=='keyframes':
        blocks=[]
        for prelude,decls in rule['blocks']:
            # keyframe selector formatting
            sel=format_keyframe_selector(prelude)
            entries=process_decl_group(decls, owner_local=None)
            blocks.append((sel,entries))
        nr=dict(rule); nr['blocks_p']=blocks; nr['processed']=True; return [nr]
    # statements etc pass
    nr=dict(rule); nr['processed']=True; return [nr]

def format_keyframe_selector(toks):
    parts=split_tok_commas(toks)
    outs=[]
    for p in parts:
        sig=strip_ws_toks(p)
        strs=[]
