            if t.type=='ident': strs.append(t.value.lower())
            elif t.type=='percentage': strs.append(fmt_num(t.value)+'%')
            else: strs.append(tok_to_css(t))
        outs.append(' '.join(strs) if False else ''.join(strs) if len(strs)<=1 else ' '.join(strs))
