    # for merging compare: serialize entries
    parts=[]
    for typ,item in body:
        if typ=='decls':
            parts.append(';'.join(e.prop+':'+e.value+('!important' if e.important else '') for e in item))
        else:
            parts.append('RULE:'+str(id(item)))
    return '|'.join(parts)

def merge_rules(rules):
    # adjacent merging iterate
    rules=list(rules)
    changed=True
    while changed:
        changed=False
        i=0
        while i < len(rules)-1:
            a=rules[i]; b=rules[i+1]
            if a.get('kind')=='style' and b.get('kind')=='style':
                if a.get('selector_str')==b.get('selector_str'):
                    # merge bodies: if both single decl group, combine entries dedup
                    ab=a['body']; bb=b['body']
                    if len(ab)==1 and len(bb)==1 and ab[0][0]=='decls' and bb[0][0]=='decls':
                        merged=dedup_entries(ab[0][1]+bb[0][1])
                        merged=sorted(merged, key=lambda e:(1 if e.important else 0, PROP_RANK.get(e.base,0) if not e.prop.startswith('--') else 0, e.seq))
                        merged=apply_prefixes(merged)
                        a=dict(a); a['body']=[('decls',merged)]
                    else:
                        a=dict(a); a['body']=ab+bb
                    rules[i]=a; del rules[i+1]; changed=True; continue
                if body_canonical(a['body'])==body_canonical(b['body']) and a['body']:
                    # merge selectors
                    a=dict(a)
                    sels=split_selector_str(a['selector_str'])
                    for s in split_selector_str(b['selector_str']):
                        if s not in sels: sels.append(s)
                    a['selector_str']=(', ' if not CTX.minify else ',').join(sels)
                    rules[i]=a; del rules[i+1]; changed=True; continue
            i+=1
    # non-adjacent subset removal
    # compute prop sets
    def prop_set(r):
        s=set()
        for typ,item in r.get('body',[]):
            if typ=='decls':
                for e in item: s.add(e.prop)
            else:
                return None
        return s
    i=0
    while i<len(rules):
        r=rules[i]
        if r.get('kind')!='style': i+=1; continue
        ps=prop_set(r)
        if ps is None or not ps: i+=1; continue
        removed=False
        for j in range(i+1, len(rules)):
            rj=rules[j]
            if rj.get('kind')!='style': continue
            if rj.get('selector_str')!=r.get('selector_str'): continue
            pj=prop_set(rj)
            if pj is not None and ps.issubset(pj):
                del rules[i]; removed=True; break
        if not removed: i+=1
    return rules

def transform_rules(rules):
    out=[]
    for r in rules:
        out.extend(transform_rule(r))
    out=merge_rules(out)
    return out

