def owner_class_from_selector(sel_toks):
    toks=strip_ws_toks(sel_toks)
    for i,t in enumerate(toks):
        if t.type=='delim' and t.value=='.' and i+1<len(toks) and toks[i+1].type=='ident':
            return toks[i+1].value
    return None

def selector_has_amp(toks):
    return any(t.type=='delim' and t.value=='&' for t in toks)

def add_amp_to_selector_toks(sel_toks):
    # For each complex selector in list, if no &, prepend '& ' (or '&' before combinator?)
    parts=split_tok_commas(sel_toks)
    out=[]
    for part in parts:
        if selector_has_amp(part):
            out.append(part)
        else:
            # Determine if part begins (after ws) with combinator: then & + that?
            sig=[t for t in part if t.type not in ('whitespace','comment')]
            if sig and sig[0].type=='delim' and sig[0].value in ('>','+','~'):
                out.append([Token('delim','&',offset=sig[0].offset), Token('whitespace',' ',offset=sig[0].offset)]+part)
            else:
                out.append([Token('delim','&',offset=0), Token('whitespace',' ',offset=0)]+part)
    # join with comma tokens
    res=[]
    for idx,part in enumerate(out):
        if idx: res.append(Token('comma',',',offset=0))
        res.extend(part)
    return res

def combine_selector_toks(parent_toks, child_toks):
    # parent and child are selector lists; produce cross product token list
    parent_parts=split_tok_commas(parent_toks)
    child_parts=split_tok_commas(child_toks)
    results=[]
    for pp in parent_parts:
        for cp in child_parts:
            if selector_has_amp(cp):
                # replace each & token with parent tokens (strip ws parent)
                new=[]
                for t in cp:
                    if t.type=='delim' and t.value=='&':
                        new.extend(pp)
                    else:
                        new.append(t)
                results.append(new)
            else:
                results.append(pp + [Token('whitespace',' ',offset=0)] + cp)
    res=[]
    for idx,part in enumerate(results):
        if idx: res.append(Token('comma',',',offset=0))
        res.extend(part)
    return res

