# ---------- Sourcemap ----------
B64='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
def vlq_encode(value):
    v = (abs(value) << 1) | (1 if value < 0 else 0)
    out=''
    while True:
        digit=v & 31
        v >>= 5
        if v: out+=B64[digit|32]
        else: out+=B64[digit]; break
    return out

def build_source_map(code, rules, source_text, source_name, tokenizer):
    segments=[] # (gen_line, gen_col, src_line, src_col)
    cursor=0
    lines=code.split('\n')
    def pos_to_linecol(pos):
        upto=code[:pos]; line=upto.count('\n'); last=upto.rfind('\n'); col=pos-last-1
        return line,col
    def find(snippet, src_offset):
        nonlocal cursor
        if not snippet: return
        pos=code.find(snippet, cursor)
        if pos==-1: pos=code.find(snippet)
        if pos==-1: return
        gl,gc=pos_to_linecol(pos)
        sl,sc=tokenizer.loc(src_offset)
        segments.append((gl,gc,sl,sc-1))
        cursor=pos+len(snippet)
    def visit(rule):
        k=rule.get('kind')
        if k=='style':
            sel=rule.get('selector_str') or ''
            find(sel, rule.get('offset',0))
            for typ,item in rule.get('body',[]):
                if typ=='rule': visit(item)
        elif k=='at_block':
            find('@'+rule['name'], rule.get('offset',0))
            for r in rule['rules']: visit(r)
        elif k=='nested_at':
            find('@'+rule['name'], rule.get('offset',0))
            for typ,item in rule.get('body',[]):
                if typ=='rule': visit(item)
        elif k in ('at_decl','at_stmt','unknown_block'):
            find('@'+rule['name'], rule.get('offset',0))
        elif k=='keyframes':
            find('@'+rule['name'], rule.get('offset',0))
            for sel,entries in rule.get('blocks_p',[]):
                # find block selector; source offset unknown: use rule offset approx? Use stored? blocks_p has no offset; use rule offset
                find(sel, rule.get('offset',0))
    for r in rules: visit(r)
    if not segments:
        mappings='AAAA'
        return json.dumps({"version":3,"mappings":mappings,"sources":[source_name],"sourcesContent":[source_text],"names":[]}, separators=(',',':'))
    segments.sort()
    max_line=max(s[0] for s in segments)
    by_line={}
    for s in segments: by_line.setdefault(s[0],[]).append(s)
    out_lines=[]
    prev_src_line=0; prev_src_col=0; prev_src_idx=0
    for ln in range(max_line+1):
        segs=sorted(by_line.get(ln,[]))
        parts=[]; prev_gen_col=0
        for gl,gc,sl,sc in segs:
            parts.append(vlq_encode(gc-prev_gen_col)+vlq_encode(0-prev_src_idx)+vlq_encode(sl-prev_src_line)+vlq_encode(sc-prev_src_col))
            prev_gen_col=gc; prev_src_line=sl; prev_src_col=sc; prev_src_idx=0
        out_lines.append(','.join(parts))
    mappings=';'.join(out_lines)
    return json.dumps({"version":3,"mappings":mappings,"sources":[source_name],"sourcesContent":[source_text],"names":[]}, separators=(',',':'))

