LATEST={'chrome':133,'edge':133,'firefox':135,'safari':18,'ios_saf':18,'opera':117,'android':133,'samsung':27,'ie':11}
def version_encode(s):
    parts=str(s).strip().split('.')
    nums=[]
    for p in parts[:3]:
        m=re.match(r'\d+',p); nums.append(int(m.group()) if m else 0)
    while len(nums)<3: nums.append(0)
    return (nums[0]<<16)|(nums[1]<<8)|nums[2]

def effective_add(targets, browser, version_str, mode='exact'):
    if browser not in ('chrome','edge','firefox','ie','ios_saf','opera','safari','android','samsung'):
        return
    v=version_encode(version_str)
    if browser in targets:
        # keep lowest
        if v<targets[browser]: targets[browser]=v
    else:
        targets[browser]=v

def parse_browserslist_query(query):
    q=query.strip()
    if q=='':
        return {}
    if q.lower().startswith('not '):
        raise TargetError(f'NotAtFirst("{query}")')
    targets={}
    # split by comma or ' and ' or newline/semicolon? Queries separated by commas; also 'or'
    parts=re.split(r',', q)
    # If no comma, whole may be single or contain ' and ' joining queries (browserslist supports and as intersection - approximate treat as list too)
    expanded=[]
    for p in parts:
        p=p.strip()
        if not p: continue
        # ' and ' between full queries ambiguous with browser query? Split if segments look like queries.
