def nodes_from_string(txt):
    tz=Tokenizer(txt)
    toks=tz.tokens(keep_whitespace=False)
    return nodes_from_tokens(toks)

def modern_replacements(node):
    # returns list of fallback css strings (lowest first) for a modern color node, or []
    if node.kind!='func': return []
    name=node.name.lower()
    if name in ('lab','lch'):
        if supports('lab'): return []
        fb=modern_color_to_fallback(node)
        return [color_to_css_context(fb)] if fb else []
    if name in ('oklab','oklch'):
        if supports('oklch'): return []
        fb=modern_color_to_fallback(node)
        rep=[]
        if fb: rep.append(color_to_css_context(fb))
        labv=color_node_lab_vals(node)
        if labv:
            L,a,b,alpha=labv
            s=f"lab({fmt_num(f32(L))}% {fmt_num(f32(a))} {fmt_num(f32(b))}"
            if alpha<1: s+=f" / {fmt_num(f32(alpha))}"
            s+=')'; rep.append(s)
        return rep
    if name=='color':
        # display-p3 etc: if not supports? add feature check simple: targets present and any browser older than safari10/chrome111 etc. Use rgb fallback if node can convert.
        if not CTX.targets_present: return []
        fb=modern_color_to_fallback(node)
        # Determine if color space is srgb (supported) vs others
        sig=[ch for ch in node.children if ch.kind=='tok']
        space=str(sig[0].tok.value).lower() if sig else ''
        if space in ('display-p3','a98-rgb','prophoto-rgb','rec2020'):
            # assume unsupported if any target is ie or major chrome<111 / safari<10 etc.
            if fb: return [color_to_css_context(fb)]
        return []
    return []

def find_modern_color_node(nodes):
    for n in nodes:
        if n.kind=='func' and n.name.lower() in ('lab','lch','oklab','oklch','color'):
            return n
        if n.children:
            r=find_modern_color_node(n.children)
            if r is not None: return r
    return None

def clone_replace_node(nodes, target, replacement_nodes):
    out=[]
    for n in nodes:
        if n is target:
            out.extend(replacement_nodes); continue
        if n.children:
            nn=Node(n.kind, tok=n.tok, name=n.name, children=clone_replace_node(n.children, target, replacement_nodes)); nn.raw_name=n.raw_name; out.append(nn); continue
        out.append(n)
    return out

